course={"id":"microprocessors","name":"Микропроцессорлық жүйелер","lang":"kk","space":"courses"}
def H(t):return f'<h2>{t}</h2>'
def LEAD(t):return f'<p class="lead">{t}</p>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def AN(t):return f'<aside class="analogy"><p>{t}</p></aside>'
def PF(t):return f'<aside class="pitfall"><p>{t}</p></aside>'
def CHECK(q,a):return f'<aside class="check"><p class="q">{q}</p><div class="a">{a}</div></aside>'

# ---------- numbers, recomputed ----------
OP,ADDR,REG=4,12,3
assert 2**4==16 and 2**6==64 and 2**7==128 and 2**8==256 and 64<70<=128
assert 2**12==4096 and 2**3==8 and 2**4==16 and 2**16==65536
assert OP+3*ADDR==40 and OP+4*ADDR==52 and 40/8==5
assert 6+3*16==54 and -(-54//8)==7 and 6+4*16==70
assert OP+2*ADDR==28 and 40-28==12
assert OP+ADDR==16 and 16//8==2
assert OP+2*REG==10 and OP+2*4==12
def three(n):return (n-1)*(OP+3*ADDR)
def acc(n):return (n+1)*(OP+ADDR)
assert three(2)==40 and acc(2)==48 and three(3)==80 and acc(3)==64
assert three(4)==120 and acc(4)==80 and 120//8==15 and 80//8==10
assert three(5)==160 and acc(5)==96
assert 3*(OP+2*REG)==30
assert all((acc(n)<three(n))==(n>=3) for n in range(2,12))
assert 100+3*2==106

